fail=0
t=$(mktemp); o=$(mktemp); e=$(mktemp)
printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\nkaede\t2026-01-05\t09:00\t10:00\tz\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty\nkaede\t2026-01-05\t09:00\t10:00\tz\n' | cmp -s - "$t" || { echo "rows after cancel differ (header, other rooms, or other bookings changed)"; fail=1; }
